<div class="entity-split"><section class="panel"><header class="panel-head"><div><span class="eyebrow">Entity navigator</span><h2>Hierarchy and service relationships</h2></div></header><div class="record-list"><?php foreach($relationships as$r): $from=entity_system_find($entities,(int)$r['from_entity_id']);$to=entity_system_find($entities,(int)$r['to_entity_id']); ?><article class="record-card relation-line"><strong><?= h($from['entity_name']??'Unknown') ?></strong><span class="status active"><?= h(status_label($r['relationship_type']).' · '.status_label($r['service_domain'])) ?></span><strong><?= h($to['entity_name']??'Unknown') ?></strong></article><?php endforeach; ?></div></section><section class="panel"><header class="panel-head"><div><span class="eyebrow">Manual relationship</span><h2>Add governed link</h2></div></header><?php if(can('companies.administer')): ?><form class="compact-form" action="<?= h(app_url('entity-system-action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_relationship"><input type="hidden" name="return_tab" value="hierarchy"><label><span>From entity</span><select name="from_entity_id"><?php foreach($entities as$e): ?><option value="<?= (int)$e['id'] ?>"><?= h($e['entity_name']) ?></option><?php endforeach; ?></select></label><label><span>To entity</span><select name="to_entity_id"><?php foreach($entities as$e): ?><option value="<?= (int)$e['id'] ?>"><?= h($e['entity_name']) ?></option><?php endforeach; ?></select></label><label><span>Relationship</span><select name="relationship_type"><option value="provides_service">Provides service</option><option value="owns">Owns</option><option value="operates">Operates</option><option value="consolidates">Consolidates</option><option value="purchases_for">Purchases for</option><option value="pays_for">Pays for</option></select></label><label><span>Domain</span><input name="service_domain" value="procurement"></label><label><span>Effective date</span><input type="date" name="effective_from" value="<?= date('Y-m-d') ?>"></label><label class="span-2"><span>Evidence</span><textarea name="evidence_note" required></textarea></label><div class="span-2"><button class="button primary">Create Relationship</button></div></form><?php endif; ?></section></div>
